from taf.ul.rfsw.ssh.exception import BranchNotSupported, NoProperUserInBranch
from taf.ul.rfsw.ssh.preferred_user import v22r1, v22r2, v22r3, v22r4, v23r1
import logging


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())
_branches_dsc_ordered = [v23r1, v22r4, v22r3, v22r2, v22r1]


def lookup_latest_branch():
    return _branches_dsc_ordered[0].__name__.split(".")[-1]


def is_supported_branch(branch_name):
    for branch in _branches_dsc_ordered:
        if branch.__name__.split(".")[-1] == branch_name:
            return True
    return False


def look_up_preferred_user(ru_name, branch_name):
    looked_up_branch_name = branch_name.lower()

    for index in range(0, len(_branches_dsc_ordered)):
        branch_name = _branches_dsc_ordered[index].__name__.split(".")[-1]
        if branch_name == looked_up_branch_name:
            break
    else:
        raise BranchNotSupported("specified branch {} is not supported".format(branch_name))

    branch = _branches_dsc_ordered[index]

    user_name = _look_up_proper_user_from_branch(branch, ru_name)
    if not user_name:
        logger.debug("looks like the preferred user name is not changed in branch {}, "
                     "will try to find it in the earlier branches".format(branch_name))

        if index == len(_branches_dsc_ordered) - 1:
            logger.debug("the branch {} is the earliest branch, no earlier ones can be looked up".format(branch_name))
            raise NoProperUserInBranch("no proper user can be found in branche {} for RU {}.".
                                       format(branch_name, ru_name))

        user_name = _look_up_proper_user_from_branches(_branches_dsc_ordered[index + 1:], ru_name)
        if not user_name:
            raise NoProperUserInBranch("the preferred user of ru {} is not supported in branches.".format(ru_name))

    return user_name


def _look_up_proper_user_from_branch(branch, ru_name):
    upper_ru_name = ru_name.upper()
    # find the user from limited user level to unlimited user level
    if upper_ru_name in branch.service_rus:
        return 'serviceuser'

    if upper_ru_name in branch.rfsw_rus:
        return 'rfsw'

    if upper_ru_name in branch.root_rus:
        return 'root'

    return None


def _look_up_proper_user_from_branches(branches, ru_name):
    for branch in branches:
        username = _look_up_proper_user_from_branch(branch, ru_name)
        if username:
            logger.debug("find the preferred username '{}' from branch '{}'".format(username, branch))
            return username
    return None


__all__ = ['look_up_preferred_user', 'is_supported_branch', 'lookup_latest_branch']
